[
  {
    "sys_fairness_reciprocity": "I owe them the same care back",
    "pd_personal_consequence_anxiety": "wondering if some official might write me up",
    "pda_self_consequence_regret": "If I got fined, I'd be sorry to lose the money",
    "sys_consequence_reasoning": "a fine weighed against five lives isn't even close to a balanced trade"
  },
  {
    "sys_fairness_reciprocity": "Everybody's life deserves the same protection",
    "pd_personal_consequence_anxiety": "half-expecting a letter saying I'd interfered with railway operations",
    "pda_self_consequence_regret": "hurt my standing, I'd be sorry about that",
    "sys_consequence_reasoning": "I'd rather answer for pulling it than for standing still",
    "pda_responsibility": "I'd rather answer for pulling it than for standing still"
  },
  {
    "pd_personal_consequence_anxiety": "whether this could cost me my job",
    "pda_self_consequence_regret": "If I did lose work over it, I'd regret that",
    "sys_consequence_reasoning": "Giving them a way out costs nobody anything comparable"
  },
  {
    "sys_fairness_reciprocity": "Their five lives weigh the same as anyone's",
    "sys_consequence_reasoning": "nobody gets hurt in the siding",
    "pd_personal_consequence_anxiety": "being questioned, maybe blamed",
    "pda_self_consequence_regret": "I'd be sorry to lose people's trust"
  },
  {
    "sys_fairness_reciprocity": "return the kindness you'd want returned",
    "pd_personal_consequence_anxiety": "a small dread about paperwork and possible charges",
    "pda_self_consequence_regret": "I'd regret the hassle and the cost",
    "sys_consequence_reasoning": "a bit of trouble for me against five people's lives is out of all proportion"
  },
  {
    "pd_personal_consequence_anxiety": "What frightens me a little is how it might look",
    "pda_self_consequence_regret": "mark on my record, I'd be genuinely sorry",
    "sys_fairness_reciprocity": "owed the same basic regard I'd expect for myself",
    "sys_consequence_reasoning": "the price to me is small by comparison"
  },
  {
    "sys_consequence_reasoning": "The harm is lopsided. At worst I face some trouble",
    "sys_fairness_reciprocity": "Each of those five matters exactly as much as I do",
    "pd_personal_consequence_anxiety": "nervous about a possible lawsuit",
    "pda_self_consequence_regret": "I'd regret any loss there"
  },
  {
    "pd_personal_consequence_anxiety": "flutter in my chest about who might come asking questions",
    "pda_self_consequence_regret": "I can picture losing a reference or looking foolish, and I'd feel that sting",
    "sys_fairness_reciprocity": "What settles it is simple reciprocity",
    "sys_consequence_reasoning": "nobody pays a price except maybe me"
  },
  {
    "sys_consequence_reasoning": "saving them costs basically nothing",
    "sys_fairness_reciprocity": "deserves the same consideration I'd claim for myself",
    "pd_personal_consequence_anxiety": "worry, I admit, about being blamed",
    "pda_self_consequence_regret": "I'd regret it if that cost me my good name"
  },
  {
    "pd_personal_consequence_anxiety": "What if I got arrested for touching equipment",
    "pda_self_consequence_regret": "Losing time with them over a legal mess is something I'd truly regret",
    "sys_fairness_reciprocity": "Equal stakes, equal care",
    "sys_consequence_reasoning": "their families deserve the same chance of having them come home"
  }
]
